def materials(type_label):
    result = []
    for case_id, domains, report, speech, facts, purpose, audience, action, question in CASES:
        if type_label == "자기소개서":
            practice = {"kind": "question", "question": question,
                        "source": "생각한줄 자체 제작 경험 중심 연습 문항"}
        else:
            speech_mode = type_label == "발표문"
            practice = {"kind": "data", "topic": speech if speech_mode else report,
                        "facts": ([f"발표 대상: {audience}."] if speech_mode else [f"보고 목적: {purpose}"])
                                 + list(facts) + ([f"청중에게 전할 요청: {action}"] if speech_mode else []),
                        "source": SOURCE, "url": "", "license": LICENSE}
        result.append({"id": f"{type_label}:{case_id}", "domains": domains, "practice": practice})
    return result
